# confidence=high  # note: Standard calculator tool: no state is read or written. Restricted the character set (digits, + - * /
def calculate(_world, expression):
    """Calculate the result of a mathematical expression.

    Read-only tool: does not touch `_world`.
    """
    if not isinstance(expression, str):
        raise ValueError("Expression must be a string")

    allowed = set("0123456789+-*/(). ")
    if not expression.strip():
        raise ValueError("Expression must not be empty")
    if not all(ch in allowed for ch in expression):
        raise ValueError(
            "Invalid characters in expression: only numbers, operators (+, -, *, /), "
            "parentheses, dots and spaces are allowed"
        )

    try:
        result = eval(expression, {"__builtins__": {}}, {})  # noqa: S307
    except ZeroDivisionError:
        raise ValueError("Invalid expression: division by zero")
    except Exception:
        raise ValueError("Invalid expression")

    if not isinstance(result, (int, float)) or isinstance(result, bool):
        raise ValueError("Invalid expression")

    return str(round(float(result), 2))

