def cancel_pending_order(_world, order_id, reason):
    """Cancel a pending order and refund the payment."""
    session = _world.get("session") or {}
    if not session.get("user_authenticated"):
        raise ValueError("User not authenticated")

    if reason not in ("no longer needed", "ordered by mistake"):
        raise ValueError(
            "Invalid reason: must be 'no longer needed' or 'ordered by mistake'"
        )

    order = _find(_world, "orders", "order_id", order_id)

    auth_user = session.get("authenticated_user_id")
    if auth_user and order.get("user_id") != auth_user:
        raise ValueError("Order does not belong to the authenticated user")

    if order.get("status") != "pending":
        raise ValueError("Non-pending order cannot be cancelled")

    transactions = _rows(_world, "payment_transactions")
    payment_methods = _rows(_world, "payment_methods")

    payments = [
        t
        for t in transactions
        if t.get("order_id") == order_id and t.get("transaction_type") == "payment"
    ]

    if not payments:
        # Fall back to the order's payment method and the sum of item prices
        total = sum(
            oi.get("price", 0)
            for oi in _rows(_world, "order_items")
            if oi.get("order_id") == order_id
        )
        payments = [
            {
                "payment_method_id": order.get("payment_method_id"),
                "amount": total,
            }
        ]

    refund_messages = []
    for idx, payment in enumerate(payments):
        pm_id = payment.get("payment_method_id")
        amount = payment.get("amount", 0)
        transactions.append(
            {
                "transaction_id": "%s_refund_%d" % (order_id, idx + 1),
                "order_id": order_id,
                "payment_method_id": pm_id,
                "transaction_type": "refund",
                "amount": amount,
            }
        )
        pm = None
        for candidate in payment_methods:
            if candidate.get("payment_method_id") == pm_id:
                pm = candidate
                break
        if pm is not None and pm.get("source") == "gift_card":
            pm["balance"] = round((pm.get("balance") or 0) + amount, 2)
            refund_messages.append(
                "%s refunded to gift card %s immediately" % (amount, pm_id)
            )
        else:
            refund_messages.append(
                "%s refunded to %s in 5-7 business days" % (amount, pm_id)
            )

    order["status"] = "cancelled"
    order["cancel_reason"] = reason

    result = dict(order)
    result["items"] = [
        {
            "item_id": oi.get("item_id"),
            "product_id": oi.get("product_id"),
            "name": oi.get("name"),
            "options": oi.get("options"),
            "price": oi.get("price"),
        }
        for oi in _rows(_world, "order_items")
        if oi.get("order_id") == order_id
    ]
    result["payment_history"] = [
        {
            "transaction_type": t.get("transaction_type"),
            "amount": t.get("amount"),
            "payment_method_id": t.get("payment_method_id"),
        }
        for t in transactions
        if t.get("order_id") == order_id
    ]
    result["refund_details"] = refund_messages
    return result

# confidence=high  # note: Gift card balance is validated but not deducted (charge happens at exchange completion, matching the
def exchange_delivered_order_items(_world, order_id, item_ids, new_item_ids, payment_method_id):
    """Exchange items in a delivered order for new items of the same product type."""
    if not isinstance(item_ids, (list, tuple)):
        raise ValueError("item_ids must be a list of item ids")
    if not isinstance(new_item_ids, (list, tuple)):
        raise ValueError("new_item_ids must be a list of item ids")
    item_ids = list(item_ids)
    new_item_ids = list(new_item_ids)
    if len(item_ids) == 0:
        raise ValueError("Error: no items to exchange")
    if len(item_ids) != len(new_item_ids):
        raise ValueError("Error: the number of items to be exchanged should match the number of new items")

    order = _find(_world, "orders", "order_id", order_id)

    # session / ownership sanity check
    session = _world.get("session") or {}
    auth_user = session.get("authenticated_user_id")
    if session.get("user_authenticated") and auth_user and auth_user != order.get("user_id"):
        raise ValueError("Error: order does not belong to the authenticated user")

    if order.get("status") != "delivered":
        raise ValueError("Error: non-delivered order cannot be exchanged")

    order_items = [oi for oi in _rows(_world, "order_items") if oi.get("order_id") == order_id]
    if not order_items:
        raise ValueError("Error: order has no items")

    # each item to exchange must be present in the order (respecting duplicates)
    all_item_ids = [oi.get("item_id") for oi in order_items]
    for item_id in item_ids:
        if item_ids.count(item_id) > all_item_ids.count(item_id):
            raise ValueError("Error: {} not found".format(item_id))

    # match each requested item id to a concrete order_item row
    used = set()
    matched = []
    for item_id in item_ids:
        row = None
        for oi in order_items:
            if oi.get("item_id") == item_id and id(oi) not in used:
                row = oi
                break
        if row is None:
            raise ValueError("Error: {} not found".format(item_id))
        if row.get("exchanged") or row.get("return_requested"):
            raise ValueError("Error: item {} has already been exchanged or returned".format(item_id))
        used.add(id(row))
        matched.append(row)

    # validate new items: exist, same product, available
    diff_price = 0.0
    new_items = []
    for row, new_item_id in zip(matched, new_item_ids):
        new_item = _find(_world, "items", "item_id", new_item_id)
        if new_item.get("product_id") != row.get("product_id"):
            raise ValueError("Error: new item {} is not of the same product".format(new_item_id))
        if not new_item.get("available"):
            raise ValueError("Error: new item {} not available".format(new_item_id))
        new_items.append(new_item)
        diff_price += float(new_item.get("price") or 0) - float(row.get("price") or 0)
    diff_price = round(diff_price, 2)

    # validate payment method
    payment_method = None
    for pm in _rows(_world, "payment_methods"):
        if pm.get("payment_method_id") == payment_method_id:
            payment_method = pm
            break
    if payment_method is None or payment_method.get("user_id") != order.get("user_id"):
        raise ValueError("Error: payment method not found")
    if payment_method.get("source") == "gift_card" and float(payment_method.get("balance") or 0) < diff_price:
        raise ValueError("Error: insufficient gift card balance to pay for the price difference")

    # apply the exchange
    for row, new_item in zip(matched, new_items):
        row["exchanged"] = True
        row["new_item_id"] = new_item.get("item_id")

    order["status"] = "exchange requested"
    order["exchange_payment_method_id"] = payment_method_id
    order["exchange_price_difference"] = diff_price

    return (
        "Exchange requested for order {}: {} item(s) will be exchanged. "
        "Price difference of ${} will be {} using {}. "
        "An email with return instructions will be sent to the user.".format(
            order_id,
            len(matched),
            abs(diff_price),
            "charged" if diff_price > 0 else "refunded",
            payment_method_id,
        )
    )

