def find_user_id_by_email(_world, email):
    """Find a user id by email address.

    Read-only lookup. Raises ValueError if no user has that email.
    """
    if not isinstance(email, str) or not email.strip():
        raise ValueError("Email must be a non-empty string")

    target = email.strip().lower()
    for user in _rows(_world, "users"):
        user_email = user.get("email")
        if isinstance(user_email, str) and user_email.strip().lower() == target:
            return user.get("user_id")

    raise ValueError("User not found")

