def get_order_details(_world, order_id):
    """Get the status and details of an order."""
    if not isinstance(order_id, str) or not order_id.strip():
        raise ValueError("order_id must be a non-empty string, such as '#W0000000'")
    order_id = order_id.strip()

    order = _find(_world, "orders", "order_id", order_id)

    # --- items in the order ---
    items = []
    for oi in _rows(_world, "order_items"):
        if oi.get("order_id") != order_id:
            continue
        entry = {
            "order_item_id": oi.get("order_item_id"),
            "item_id": oi.get("item_id"),
            "product_id": oi.get("product_id"),
            "name": oi.get("name"),
            "options": oi.get("options"),
            "price": oi.get("price"),
        }
        if oi.get("exchanged"):
            entry["exchanged"] = True
            entry["new_item_id"] = oi.get("new_item_id")
        if oi.get("return_requested"):
            entry["return_requested"] = True
        items.append(entry)

    # --- fulfillments ---
    fulfillments = []
    for f in _rows(_world, "fulfillments"):
        if f.get("order_id") != order_id:
            continue
        tracking_id = f.get("tracking_id")
        item_ids = [
            fi.get("item_id")
            for fi in _rows(_world, "fulfillment_items")
            if fi.get("order_id") == order_id and fi.get("tracking_id") == tracking_id
        ]
        fulfillments.append({"tracking_id": tracking_id, "item_ids": item_ids})

    # --- payment history ---
    payment_history = []
    for t in _rows(_world, "payment_transactions"):
        if t.get("order_id") != order_id:
            continue
        payment_history.append({
            "transaction_id": t.get("transaction_id"),
            "transaction_type": t.get("transaction_type"),
            "amount": t.get("amount"),
            "payment_method_id": t.get("payment_method_id"),
        })

    result = {
        "order_id": order.get("order_id"),
        "user_id": order.get("user_id"),
        "status": order.get("status"),
        "address": {
            "address1": order.get("address1"),
            "address2": order.get("address2"),
            "city": order.get("city"),
            "state": order.get("state"),
            "country": order.get("country"),
            "zip": order.get("zip"),
        },
        "items": items,
        "fulfillments": fulfillments,
        "payment_history": payment_history,
    }

    if order.get("payment_method_id"):
        result["payment_method_id"] = order.get("payment_method_id")
    if order.get("cancel_reason"):
        result["cancel_reason"] = order.get("cancel_reason")
    if order.get("items_modified"):
        result["items_modified"] = True
    if order.get("exchange_payment_method_id"):
        result["exchange_payment_method_id"] = order.get("exchange_payment_method_id")
        result["exchange_price_difference"] = order.get("exchange_price_difference")

    return result

