def get_user_details(_world, user_id):
    """Get the details of a user, including their orders."""
    if not user_id or not isinstance(user_id, str):
        raise ValueError("user_id must be a non-empty string")

    user = _find(_world, "users", "user_id", user_id)

    payment_methods = {}
    for pm in _rows(_world, "payment_methods"):
        if pm.get("user_id") != user_id:
            continue
        entry = {
            "source": pm.get("source"),
            "id": pm.get("payment_method_id"),
        }
        if pm.get("source") == "gift_card":
            entry["balance"] = pm.get("balance")
        else:
            if pm.get("brand") is not None:
                entry["brand"] = pm.get("brand")
            if pm.get("last_four") is not None:
                entry["last_four"] = pm.get("last_four")
        payment_methods[pm.get("payment_method_id")] = entry

    orders = [
        o.get("order_id")
        for o in _rows(_world, "orders")
        if o.get("user_id") == user_id
    ]

    return {
        "user_id": user.get("user_id"),
        "name": {
            "first_name": user.get("first_name"),
            "last_name": user.get("last_name"),
        },
        "email": user.get("email"),
        "address": {
            "address1": user.get("address1"),
            "address2": user.get("address2"),
            "city": user.get("city"),
            "state": user.get("state"),
            "country": user.get("country"),
            "zip": user.get("zip"),
        },
        "payment_methods": payment_methods,
        "orders": orders,
    }

# confidence=high  # note: Returns a name -> product_id dict (matching the tau-bench retail convention); duplicate product name
def list_all_product_types(_world):
    """List the name and product id of all product types.

    Returns a mapping of product name -> product id, sorted by name.
    """
    products = _rows(_world, "products")
    result = {}
    for product in sorted(products, key=lambda p: str(p.get("name", ""))):
        name = product.get("name")
        product_id = product.get("product_id")
        if name is None:
            name = product_id
        result[str(name)] = product_id
    return result

