def modify_pending_order_items(_world, order_id, item_ids, new_item_ids, payment_method_id):
    session = _world.get("session") or {}
    if not session.get("user_authenticated"):
        raise ValueError("User not authenticated")

    if not isinstance(order_id, str) or not order_id.startswith("#"):
        raise ValueError("Invalid order id: order id should start with '#'")

    order = _find(_world, "orders", "order_id", order_id)

    auth_user_id = session.get("authenticated_user_id")
    if auth_user_id and order.get("user_id") != auth_user_id:
        raise ValueError("Order does not belong to the authenticated user")

    if order.get("status") != "pending":
        raise ValueError("Non-pending order cannot be modified")

    if order.get("items_modified"):
        raise ValueError("Items of this order have already been modified")

    if not isinstance(item_ids, list) or not isinstance(new_item_ids, list):
        raise ValueError("item_ids and new_item_ids must be lists")
    if len(item_ids) == 0:
        raise ValueError("No items to modify")
    if len(item_ids) != len(new_item_ids):
        raise ValueError("The number of items to be modified should match the number of new items")

    order_items = [oi for oi in _rows(_world, "order_items") if oi.get("order_id") == order_id]

    # Match each requested item id to a distinct order item row
    remaining = list(order_items)
    matched = []
    for item_id in item_ids:
        found = None
        for oi in remaining:
            if oi.get("item_id") == item_id:
                found = oi
                break
        if found is None:
            raise ValueError("Item {} not found in order {}".format(item_id, order_id))
        remaining.remove(found)
        matched.append(found)

    all_items = _rows(_world, "items")

    # Validate new items: exist, same product, available
    new_items = []
    for order_item, new_item_id in zip(matched, new_item_ids):
        new_item = None
        for it in all_items:
            if it.get("item_id") == new_item_id:
                new_item = it
                break
        if new_item is None:
            raise ValueError("New item {} not found".format(new_item_id))
        if new_item.get("product_id") != order_item.get("product_id"):
            raise ValueError(
                "New item {} does not belong to the same product as item {}".format(
                    new_item_id, order_item.get("item_id")
                )
            )
        if not new_item.get("available"):
            raise ValueError("New item {} is not available".format(new_item_id))
        new_items.append(new_item)

    # Validate payment method
    payment_method = None
    for pm in _rows(_world, "payment_methods"):
        if pm.get("payment_method_id") == payment_method_id:
            payment_method = pm
            break
    if payment_method is None:
        raise ValueError("Payment method {} not found".format(payment_method_id))
    if payment_method.get("user_id") != order.get("user_id"):
        raise ValueError("Payment method does not belong to the user of this order")

    # Price difference
    diff_price = 0.0
    for order_item, new_item in zip(matched, new_items):
        diff_price += (new_item.get("price") or 0) - (order_item.get("price") or 0)
    diff_price = round(diff_price, 2)

    if payment_method.get("source") == "gift_card" and diff_price > 0:
        if (payment_method.get("balance") or 0) < diff_price:
            raise ValueError("Insufficient gift card balance to pay for the price difference")

    # Apply modifications
    for order_item, new_item in zip(matched, new_items):
        order_item["item_id"] = new_item.get("item_id")
        order_item["price"] = new_item.get("price")
        order_item["options"] = new_item.get("options")

    transactions = _rows(_world, "payment_transactions")
    if diff_price != 0:
        transactions.append(
            {
                "transaction_id": "{}_{}".format(order_id, len(transactions) + 1),
                "order_id": order_id,
                "payment_method_id": payment_method_id,
                "transaction_type": "payment" if diff_price > 0 else "refund",
                "amount": abs(diff_price),
            }
        )

    if payment_method.get("source") == "gift_card":
        payment_method["balance"] = round((payment_method.get("balance") or 0) - diff_price, 2)

    order["status"] = "pending (items modified)"
    order["items_modified"] = True
    order["payment_method_id"] = payment_method_id

    updated_items = [
        {
            "item_id": oi.get("item_id"),
            "product_id": oi.get("product_id"),
            "name": oi.get("name"),
            "options": oi.get("options"),
            "price": oi.get("price"),
        }
        for oi in order_items
    ]

    return {
        "order_id": order_id,
        "user_id": order.get("user_id"),
        "status": order["status"],
        "items": updated_items,
        "price_difference": diff_price,
        "payment_method_id": payment_method_id,
        "message": "Order {} items modified. Price difference: {}.".format(order_id, diff_price),
    }

# confidence=high  # note: Assumed the order total equals net (payments minus refunds) of existing payment_transactions, fallin
def modify_pending_order_payment(_world, order_id, payment_method_id):
    session = _world.get("session", {})
    if not session.get("user_authenticated"):
        raise ValueError("User not authenticated")

    order = _find(_world, "orders", "order_id", order_id)

    auth_user = session.get("authenticated_user_id")
    if auth_user and order.get("user_id") != auth_user:
        raise ValueError("Order does not belong to the authenticated user")

    if order.get("status") != "pending":
        raise ValueError("Non-pending order cannot be modified")

    payment_method = _find(
        _world, "payment_methods", "payment_method_id", payment_method_id
    )
    if payment_method.get("user_id") != order.get("user_id"):
        raise ValueError("Payment method does not belong to the user of this order")

    transactions = [
        t for t in _rows(_world, "payment_transactions")
        if t.get("order_id") == order_id
    ]

    original_payment_method_id = order.get("payment_method_id")
    if not original_payment_method_id:
        for t in transactions:
            if t.get("transaction_type") == "payment":
                original_payment_method_id = t.get("payment_method_id")
                break
    if not original_payment_method_id:
        raise ValueError("Original payment method not found for this order")

    if payment_method_id == original_payment_method_id:
        raise ValueError(
            "The new payment method should be different from the original payment method"
        )

    # Amount currently paid for the order
    amount = 0.0
    for t in transactions:
        if t.get("transaction_type") == "payment":
            amount += t.get("amount", 0)
        elif t.get("transaction_type") == "refund":
            amount -= t.get("amount", 0)
    if round(amount, 2) <= 0:
        amount = sum(
            oi.get("price", 0)
            for oi in _rows(_world, "order_items")
            if oi.get("order_id") == order_id
        )
    amount = round(amount, 2)

    if payment_method.get("source") == "gift_card" and \
            payment_method.get("balance", 0) < amount:
        raise ValueError("Insufficient gift card balance to pay for the order")

    original_payment_method = _find(
        _world, "payment_methods", "payment_method_id", original_payment_method_id
    )

    all_transactions = _rows(_world, "payment_transactions")
    next_index = len(all_transactions) + 1

    def _new_id():
        nonlocal next_index
        while True:
            candidate = "txn_%07d" % next_index
            next_index += 1
            if not any(t.get("transaction_id") == candidate for t in all_transactions):
                return candidate

    all_transactions.append({
        "transaction_id": _new_id(),
        "order_id": order_id,
        "payment_method_id": payment_method_id,
        "transaction_type": "payment",
        "amount": amount,
    })
    all_transactions.append({
        "transaction_id": _new_id(),
        "order_id": order_id,
        "payment_method_id": original_payment_method_id,
        "transaction_type": "refund",
        "amount": amount,
    })

    if payment_method.get("source") == "gift_card":
        payment_method["balance"] = round(payment_method.get("balance", 0) - amount, 2)
    if original_payment_method.get("source") == "gift_card":
        original_payment_method["balance"] = round(
            original_payment_method.get("balance", 0) + amount, 2
        )

    order["payment_method_id"] = payment_method_id
    order["status"] = "pending"

    if original_payment_method.get("source") == "gift_card":
        refund_note = "refunded to the original gift card immediately"
    else:
        refund_note = "refunded to the original payment method in 5 to 7 business days"

    return (
        "Order %s payment method changed to %s for a total of %.2f. The original "
        "amount was %s. Order status remains pending."
        % (order_id, payment_method_id, amount, refund_note)
    )

# confidence=high  # note: Assumed the policy's authentication requirement is a precondition: the session must be authenticated
def modify_user_address(_world, user_id, address1, address2, city, state, country, zip):
    session = _world.get("session") or {}
    if not session.get("user_authenticated"):
        raise ValueError("User not authenticated: authenticate the user identity first.")

    auth_id = session.get("authenticated_user_id")
    if auth_id and auth_id != user_id:
        raise ValueError(
            "Cannot modify address for a different user than the authenticated user "
            f"'{auth_id}'."
        )

    user = _find(_world, "users", "user_id", user_id)

    user["address1"] = address1
    user["address2"] = address2
    user["city"] = city
    user["state"] = state
    user["country"] = country
    user["zip"] = zip

    return {
        "user_id": user.get("user_id"),
        "first_name": user.get("first_name"),
        "last_name": user.get("last_name"),
        "email": user.get("email"),
        "address1": user.get("address1"),
        "address2": user.get("address2"),
        "city": user.get("city"),
        "state": user.get("state"),
        "country": user.get("country"),
        "zip": user.get("zip"),
    }

# confidence=high  # note: Schema has no dedicated 'return_payment_method_id' field, so the refund destination is stored in ord
def return_delivered_order_items(_world, order_id, item_ids, payment_method_id):
    # --- locate the order ---
    order = _find(_world, "orders", "order_id", order_id)

    if order.get("status") != "delivered":
        raise ValueError(
            "Non-delivered order cannot be returned (current status: %s)"
            % order.get("status")
        )

    if not isinstance(item_ids, (list, tuple)):
        raise ValueError("item_ids must be a list of item ids")
    item_ids = list(item_ids)
    if len(item_ids) == 0:
        raise ValueError("No item ids provided to return")

    # --- validate payment method ---
    payment_method = None
    for pm in _rows(_world, "payment_methods"):
        if pm.get("payment_method_id") == payment_method_id:
            payment_method = pm
            break
    if payment_method is None:
        raise ValueError("Payment method not found")

    if payment_method.get("user_id") != order.get("user_id"):
        raise ValueError("Payment method does not belong to the user of this order")

    original_payment_method_id = order.get("payment_method_id")
    is_gift_card = str(payment_method.get("source", "")).startswith("gift_card")
    if payment_method_id != original_payment_method_id and not is_gift_card:
        raise ValueError(
            "Refund must either go to the original payment method, or an existing gift card"
        )

    # --- validate the items belong to the order and are not already return requested ---
    order_rows = [
        oi for oi in _rows(_world, "order_items") if oi.get("order_id") == order_id
    ]

    matched = []
    used = set()
    for iid in item_ids:
        found = None
        for idx, oi in enumerate(order_rows):
            if idx in used:
                continue
            if oi.get("item_id") != iid:
                continue
            if oi.get("return_requested"):
                continue
            found = idx
            break
        if found is None:
            raise ValueError("Item %s not found in the order or already returned" % iid)
        used.add(found)
        matched.append(order_rows[found])

    # --- apply changes ---
    total_refund = 0
    returned_items = []
    for oi in matched:
        oi["return_requested"] = True
        total_refund += oi.get("price", 0) or 0
        returned_items.append(oi.get("item_id"))

    order["status"] = "return requested"
    # closest existing field to record where the refund should go
    order["exchange_payment_method_id"] = payment_method_id

    return (
        "Order %s status changed to 'return requested'. Items to return: %s. "
        "Refund of $%s will be issued to %s after the items are received. "
        "The user will receive a follow-up email with return instructions."
        % (
            order_id,
            ", ".join(returned_items),
            round(total_refund, 2),
            payment_method_id,
        )
    )

# confidence=high  # note: Assumed no authentication precondition for transfers (a user who cannot be authenticated may still n
def transfer_to_human_agents(_world, summary):
    if summary is None or not str(summary).strip():
        raise ValueError("A summary of the user's issue is required.")

    session = _world.get("session")
    if not isinstance(session, dict):
        session = {}
        _world["session"] = session

    if session.get("transferred_to_human_agent"):
        raise ValueError("The user has already been transferred to a human agent.")

    session["transferred_to_human_agent"] = True
    session["transfer_summary"] = str(summary).strip()

    return "Transfer successful"

# ---- derived state: recomputed after every call, like a database trigger
def derive(state):
    def _num(x):
        try:
            return float(x)
        except (TypeError, ValueError):
            return 0.0

    def _addr(d):
        parts = [d.get("address1"), d.get("address2"), d.get("city"),
                 d.get("state"), d.get("zip"), d.get("country")]
        return ", ".join([str(p).strip() for p in parts if p not in (None, "")])

    users = state.get("users") or []
    pms = state.get("payment_methods") or []
    products = state.get("products") or []
    items = state.get("items") or []
    orders = state.get("orders") or []
    order_items = state.get("order_items") or []
    fulfillments = state.get("fulfillments") or []
    fulfillment_items = state.get("fulfillment_items") or []
    txns = state.get("payment_transactions") or []
    session = state.setdefault("session", {})

    item_by_id = {}
    for i in items:
        item_by_id[i.get("item_id")] = i
    product_by_id = {}
    for p in products:
        product_by_id[p.get("product_id")] = p

    # ---- products ----
    items_by_product = {}
    for i in items:
        items_by_product.setdefault(i.get("product_id"), []).append(i)
    for p in products:
        vs = items_by_product.get(p.get("product_id"), [])
        av = [i for i in vs if bool(i.get("available"))]
        p["item_ids"] = sorted([str(i.get("item_id")) for i in vs if i.get("item_id")])
        p["available_item_ids"] = sorted([str(i.get("item_id")) for i in av if i.get("item_id")])
        p["variant_count"] = len(vs)
        p["available_variant_count"] = len(av)
        p["in_stock"] = len(av) > 0
        prices = [_num(i.get("price")) for i in av]
        p["min_available_price"] = round(min(prices), 2) if prices else None
        p["max_available_price"] = round(max(prices), 2) if prices else None

    # ---- items ----
    order_count_by_item = {}
    for oi in order_items:
        k = oi.get("item_id")
        order_count_by_item[k] = order_count_by_item.get(k, 0) + 1
    for i in items:
        prod = product_by_id.get(i.get("product_id"))
        i["product_name"] = prod.get("name") if prod else None
        i["times_ordered"] = order_count_by_item.get(i.get("item_id"), 0)

    # ---- payment methods ----
    for pm in pms:
        src = (pm.get("source") or "").lower()
        pm["is_gift_card"] = src == "gift_card"
        pm["available_balance"] = round(_num(pm.get("balance")), 2) if src == "gift_card" else None
        if src == "gift_card":
            pm["display"] = "gift card ending in " + str(pm.get("last_four") or "")
        elif src == "credit_card":
            pm["display"] = str(pm.get("brand") or "card") + " ending in " + str(pm.get("last_four") or "")
        else:
            pm["display"] = src or "unknown"
    pm_by_id = {}
    for pm in pms:
        pm_by_id[pm.get("payment_method_id")] = pm

    # ---- order items ----
    for oi in order_items:
        old_price = round(_num(oi.get("price")), 2)
        new_id = oi.get("new_item_id")
        new_it = item_by_id.get(new_id) if new_id else None
        oi["new_item_price"] = round(_num(new_it.get("price")), 2) if new_it else None
        oi["new_item_options"] = new_it.get("options") if new_it else None
        replaced = bool(oi.get("exchanged")) or bool(new_id)
        if new_it and replaced:
            oi["price_difference"] = round(_num(new_it.get("price")) - old_price, 2)
        else:
            oi["price_difference"] = 0.0
        oi["replacement_valid"] = bool(
            new_it is not None
            and new_it.get("product_id") == oi.get("product_id")
            and new_id != oi.get("item_id")
            and bool(new_it.get("available"))
        )
        oi["exchange_valid"] = bool(oi.get("exchanged")) and oi["replacement_valid"]
        oi["is_pending_return"] = bool(oi.get("return_requested"))

    # ---- grouping ----
    oi_by_order = {}
    for oi in order_items:
        oi_by_order.setdefault(oi.get("order_id"), []).append(oi)
    tx_by_order = {}
    for t in txns:
        tx_by_order.setdefault(t.get("order_id"), []).append(t)
    ff_by_order = {}
    for f in fulfillments:
        ff_by_order.setdefault(f.get("order_id"), []).append(f)
    fi_by_order = {}
    for f in fulfillment_items:
        fi_by_order.setdefault(f.get("order_id"), []).append(f)

    # ---- orders ----
    for o in orders:
        oid = o.get("order_id")
        ois = oi_by_order.get(oid, [])
        txs = tx_by_order.get(oid, [])
        status = (o.get("status") or "").strip().lower()

        o["status_normalized"] = status
        o["item_ids"] = [x.get("item_id") for x in ois]
        o["item_count"] = len(ois)
        subtotal = round(sum(_num(x.get("price")) for x in ois), 2)
        diff = round(_num(o.get("exchange_price_difference")), 2)
        o["subtotal"] = subtotal
        o["total"] = round(subtotal + diff, 2)

        paid = round(sum(_num(t.get("amount")) for t in txs
                         if (t.get("transaction_type") or "").lower() == "payment"), 2)
        refunded = round(sum(_num(t.get("amount")) for t in txs
                             if (t.get("transaction_type") or "").lower() == "refund"), 2)
        o["amount_paid"] = paid
        o["amount_refunded"] = refunded
        o["net_paid"] = round(paid - refunded, 2)

        o["tracking_ids"] = sorted([str(f.get("tracking_id")) for f in ff_by_order.get(oid, [])
                                    if f.get("tracking_id")])
        fulfilled = sorted([str(f.get("item_id")) for f in fi_by_order.get(oid, [])
                            if f.get("item_id")])
        o["fulfilled_item_ids"] = fulfilled
        o["is_fulfilled"] = bool(ois) and fulfilled == sorted([str(x.get("item_id")) for x in ois])

        o["shipping_address"] = _addr(o)
        o["address_complete"] = all(str(o.get(k) or "").strip() != ""
                                    for k in ("address1", "city", "country", "zip"))

        o["is_pending"] = status.startswith("pending")
        o["can_cancel"] = status == "pending"
        o["can_modify_address"] = status == "pending"
        o["can_modify_payment"] = status == "pending"
        o["can_modify_items"] = status == "pending" and not bool(o.get("items_modified"))
        o["can_return"] = status == "delivered" and any(not bool(x.get("return_requested")) for x in ois)
        o["can_exchange"] = status == "delivered" and any(not bool(x.get("exchanged")) for x in ois)

        o["return_requested_item_ids"] = [x.get("item_id") for x in ois if bool(x.get("return_requested"))]
        o["exchanged_item_ids"] = [x.get("item_id") for x in ois if bool(x.get("exchanged"))]
        o["replaced_item_ids"] = [x.get("item_id") for x in ois if x.get("new_item_id")]

        computed = round(sum(x.get("price_difference") or 0.0 for x in ois
                             if bool(x.get("exchanged")) or x.get("new_item_id")), 2)
        o["computed_exchange_price_difference"] = computed
        o["exchange_difference_matches"] = abs(diff - computed) < 0.01
        o["all_replacements_valid"] = all(x.get("replacement_valid") for x in ois if x.get("new_item_id"))
        o["all_exchanges_valid"] = all(x.get("exchange_valid") for x in ois if bool(x.get("exchanged")))

        if status == "cancelled":
            o["is_settled"] = abs(o["net_paid"]) < 0.01
        else:
            o["is_settled"] = abs(o["net_paid"] - o["total"]) < 0.01
        o["awaiting_refund"] = status in ("cancelled", "return requested") and o["net_paid"] > 0.01

        pm = pm_by_id.get(o.get("payment_method_id"))
        o["payment_method_valid"] = bool(pm is not None and pm.get("user_id") == o.get("user_id"))
        epm_id = o.get("exchange_payment_method_id")
        epm = pm_by_id.get(epm_id) if epm_id else None
        o["exchange_payment_method_valid"] = bool(epm is not None and epm.get("user_id") == o.get("user_id"))

    # ---- users ----
    orders_by_user = {}
    for o in orders:
        orders_by_user.setdefault(o.get("user_id"), []).append(o)
    pms_by_user = {}
    for pm in pms:
        pms_by_user.setdefault(pm.get("user_id"), []).append(pm)
    for u in users:
        uid = u.get("user_id")
        uos = orders_by_user.get(uid, [])
        upms = pms_by_user.get(uid, [])
        u["full_name"] = (str(u.get("first_name") or "") + " " + str(u.get("last_name") or "")).strip()
        u["default_address"] = _addr(u)
        u["order_ids"] = sorted([str(o.get("order_id")) for o in uos if o.get("order_id")])
        u["order_count"] = len(uos)
        u["payment_method_ids"] = sorted([str(p.get("payment_method_id")) for p in upms
                                          if p.get("payment_method_id")])
        u["gift_card_balance_total"] = round(sum(_num(p.get("balance")) for p in upms
                                                 if (p.get("source") or "").lower() == "gift_card"), 2)
        u["pending_order_ids"] = sorted([str(o.get("order_id")) for o in uos
                                         if (o.get("status") or "").lower().startswith("pending")])
        u["delivered_order_ids"] = sorted([str(o.get("order_id")) for o in uos
                                           if (o.get("status") or "").lower() == "delivered"])

    # ---- session ----
    auth_id = session.get("authenticated_user_id")
    known = set([u.get("user_id") for u in users])
    session["auth_valid"] = bool(session.get("user_authenticated")) and auth_id in known
    session["authenticated_user_order_ids"] = sorted(
        [str(o.get("order_id")) for o in orders_by_user.get(auth_id, []) if o.get("order_id")]
    ) if session["auth_valid"] else []
    session["transfer_complete"] = bool(session.get("transferred_to_human_agent")) and \
        str(session.get("transfer_summary") or "").strip() != ""

    return state

# The session is authenticated and the authenticated user id refers to a real user in the database.
def user_authenticated(state):
    session = state.get("session") or {}
    if not session.get("user_authenticated"):
        return False
    uid = session.get("authenticated_user_id")
    return any(u.get("user_id") == uid for u in (state.get("users") or []))

# At least one order is cancelled and every cancelled order has an allowed reason and has been fully refunded.
def all_cancellations_complete(state):
    allowed = {"no longer needed", "ordered by mistake"}
    found = False
    for o in (state.get("orders") or []):
        if (o.get("status") or "").strip().lower() != "cancelled":
            continue
        found = True
        if str(o.get("cancel_reason") or "").strip().lower() not in allowed:
            return False
        if abs(float(o.get("net_paid") or 0.0)) >= 0.01:
            return False
    return True   # vacuously true: a universally quantified claim holds over an empty set

# At least one order is in 'return requested' state and every such order flags concrete items to return and has a valid refund payment method.
def all_return_requests_complete(state):
    ois = state.get("order_items") or []
    found = False
    for o in (state.get("orders") or []):
        if (o.get("status") or "").strip().lower() != "return requested":
            continue
        found = True
        mine = [x for x in ois if x.get("order_id") == o.get("order_id")]
        if not any(bool(x.get("return_requested")) for x in mine):
            return False
        if not o.get("payment_method_valid"):
            return False
    return True   # vacuously true: a universally quantified claim holds over an empty set

# At least one order is in 'exchange requested' state and every such order has valid same-product replacements, a valid payment method, and a price difference matching the recomputed one.
def all_exchange_requests_complete(state):
    ois = state.get("order_items") or []
    found = False
    for o in (state.get("orders") or []):
        if (o.get("status") or "").strip().lower() != "exchange requested":
            continue
        found = True
        mine = [x for x in ois if x.get("order_id") == o.get("order_id")]
        exch = [x for x in mine if bool(x.get("exchanged"))]
        if not exch:
            return False
        if not all(x.get("exchange_valid") for x in exch):
            return False
        if not o.get("exchange_payment_method_valid"):
            return False
        if not o.get("exchange_difference_matches"):
            return False
    return True   # vacuously true: a universally quantified claim holds over an empty set

# At least one pending order had its items modified, and every modified order still holds pending status with valid same-product replacements and a valid payment method.
def all_item_modifications_valid(state):
    ois = state.get("order_items") or []
    found = False
    for o in (state.get("orders") or []):
        if not bool(o.get("items_modified")):
            continue
        found = True
        if not (o.get("status") or "").strip().lower().startswith("pending"):
            return False
        mine = [x for x in ois if x.get("order_id") == o.get("order_id")]
        repl = [x for x in mine if x.get("new_item_id")]
        if not repl:
            return False
        if not all(x.get("replacement_valid") for x in repl):
            return False
        if not o.get("payment_method_valid"):
            return False
    return True   # vacuously true: a universally quantified claim holds over an empty set

# Every order's net money movement matches its computed total (zero for cancelled orders), i.e. no refund or charge is outstanding.
def all_orders_financially_settled(state):
    orders = state.get("orders") or []
    if not orders:
        return False
    return all(bool(o.get("is_settled")) for o in orders)

# Every order carries a shippable address (address1, city, country and zip all filled in).
def all_orders_have_complete_address(state):
    orders = state.get("orders") or []
    if not orders:
        return False
    return all(bool(o.get("address_complete")) for o in orders)

# The conversation was handed off to a human agent with a non-empty summary.
def transfer_completed(state):
    session = state.get("session") or {}
    return bool(session.get("transferred_to_human_agent")) and \
        str(session.get("transfer_summary") or "").strip() != ""

# Only orders belonging to the currently authenticated user have been cancelled, returned, exchanged, or item-modified.
def no_out_of_scope_orders_touched(state):
    session = state.get("session") or {}
    if not session.get("auth_valid"):
        return False
    uid = session.get("authenticated_user_id")
    touched_states = {"cancelled", "return requested", "exchange requested"}
    for o in (state.get("orders") or []):
        status = (o.get("status") or "").strip().lower()
        if status in touched_states or bool(o.get("items_modified")):
            if o.get("user_id") != uid:
                return False
    return True

