# A healthy world. Every predicate above holds on it; that is what makes it
# possible to BREAK it and prove the break was repaired.

def _now(state):
    """The world's current time, from `state["meta"]["now"]`.

    A single addressable fact rather than a literal repeated in three tool bodies. Never
    `datetime.now()`: a clock that follows the wall makes the same case pass today and
    fail tomorrow, and this environment exists so that nothing moves except the agent.
    """
    from datetime import datetime as _dtc
    raw = ((state or {}).get("meta") or {}).get("now")
    if not raw:
        raise ValueError(
            "This world carries no clock. Every environment must seed "
            "meta.now; see scripts/add_world_clock.py.")
    return _dtc.fromisoformat(str(raw).replace("Z", "+00:00").replace("+00:00", ""))

