def apply(state, tool, **args):
    """Call a tool and re-derive. The only supported way to change the world.

    Calling a tool without re-deriving leaves observables stale, which is how a broken
    world can look healthy — the failure mode this whole environment exists to prevent.
    """
    result = TOOLS[tool](state, **args)
    derive(state)
    return result


def evaluate(state):
    """Every predicate, by name. -> {name: bool}"""
    return {n: bool(f(state)) for n, f in PREDICATES.items()}


# ---- conditions that are NOT health -----------------------------------------
#
# Both kinds are false on every healthy world BY CONSTRUCTION, so leaving them in
# PREDICATES made `all(evaluate(world).values())` unsatisfiable and killed the guard
# that rejects a world where nothing broke. They stay in the module because the rule
# IR needs them; they leave the health set because they are not health.

# Records that something HAPPENED. Never a property of a healthy world.
OUTCOMES = {
    # records that an escalation HAPPENED; true only on a world where the case was handed off, which is never a healthy one
    "transfer_completed": transfer_completed,
}
